import type { SyncDocument } from './types'

const HANDLE_STORE = 'handles'
const DOCS_STORE = 'documents'
const META_STORE = 'meta'
const HANDLE_KEY = 'syncDirectory'

export interface LocalSyncDb {
  dbName: string
  close: () => void
  getHandle: () => Promise<FileSystemDirectoryHandle | null>
  setHandle: (handle: FileSystemDirectoryHandle | null) => Promise<void>
  getDoc: (collection: string, id: string) => Promise<SyncDocument | null>
  putDoc: (doc: SyncDocument) => Promise<void>
  deleteDocKey: (collection: string, id: string) => Promise<void>
  listDocs: (collection: string) => Promise<SyncDocument[]>
  listAllDocs: () => Promise<SyncDocument[]>
  getMeta: <T>(key: string) => Promise<T | null>
  setMeta: (key: string, value: unknown) => Promise<void>
}

function docKey(collection: string, id: string): string {
  return `${collection}/${id}`
}

export function openLocalSyncDb(dbName: string): Promise<LocalSyncDb> {
  return new Promise((resolve, reject) => {
    if (typeof indexedDB === 'undefined') {
      reject(new Error('IndexedDB is not available'))
      return
    }
    const req = indexedDB.open(dbName, 1)
    req.onerror = () => reject(req.error ?? new Error('IndexedDB open failed'))
    req.onupgradeneeded = () => {
      const db = req.result
      if (!db.objectStoreNames.contains(HANDLE_STORE)) {
        db.createObjectStore(HANDLE_STORE)
      }
      if (!db.objectStoreNames.contains(DOCS_STORE)) {
        const store = db.createObjectStore(DOCS_STORE, { keyPath: 'key' })
        store.createIndex('collection', 'collection', { unique: false })
      }
      if (!db.objectStoreNames.contains(META_STORE)) {
        db.createObjectStore(META_STORE)
      }
    }
    req.onsuccess = () => {
      const db = req.result
      resolve(wrapDb(dbName, db))
    }
  })
}

function wrapDb(dbName: string, db: IDBDatabase): LocalSyncDb {
  function txDone(tx: IDBTransaction): Promise<void> {
    return new Promise((resolve, reject) => {
      tx.oncomplete = () => resolve()
      tx.onerror = () => reject(tx.error)
      tx.onabort = () => reject(tx.error ?? new Error('IndexedDB transaction aborted'))
    })
  }

  return {
    dbName,
    close: () => db.close(),

    async getHandle() {
      return new Promise((resolve, reject) => {
        const tx = db.transaction(HANDLE_STORE, 'readonly')
        const req = tx.objectStore(HANDLE_STORE).get(HANDLE_KEY)
        req.onsuccess = () =>
          resolve((req.result as FileSystemDirectoryHandle) ?? null)
        req.onerror = () => reject(req.error)
      })
    },

    async setHandle(handle) {
      const tx = db.transaction(HANDLE_STORE, 'readwrite')
      const store = tx.objectStore(HANDLE_STORE)
      if (handle) store.put(handle, HANDLE_KEY)
      else store.delete(HANDLE_KEY)
      await txDone(tx)
    },

    async getDoc(collection, id) {
      return new Promise((resolve, reject) => {
        const tx = db.transaction(DOCS_STORE, 'readonly')
        const req = tx.objectStore(DOCS_STORE).get(docKey(collection, id))
        req.onsuccess = () => {
          const row = req.result as { doc?: SyncDocument } | undefined
          resolve(row?.doc ?? null)
        }
        req.onerror = () => reject(req.error)
      })
    },

    async putDoc(doc) {
      const tx = db.transaction(DOCS_STORE, 'readwrite')
      tx.objectStore(DOCS_STORE).put({
        key: docKey(doc.collection, doc.id),
        collection: doc.collection,
        id: doc.id,
        doc,
      })
      await txDone(tx)
    },

    async deleteDocKey(collection, id) {
      const tx = db.transaction(DOCS_STORE, 'readwrite')
      tx.objectStore(DOCS_STORE).delete(docKey(collection, id))
      await txDone(tx)
    },

    async listDocs(collection) {
      return new Promise((resolve, reject) => {
        const tx = db.transaction(DOCS_STORE, 'readonly')
        const index = tx.objectStore(DOCS_STORE).index('collection')
        const req = index.getAll(collection)
        req.onsuccess = () => {
          const rows = (req.result ?? []) as { doc: SyncDocument }[]
          resolve(rows.map((r) => r.doc).filter(Boolean))
        }
        req.onerror = () => reject(req.error)
      })
    },

    async listAllDocs() {
      return new Promise((resolve, reject) => {
        const tx = db.transaction(DOCS_STORE, 'readonly')
        const req = tx.objectStore(DOCS_STORE).getAll()
        req.onsuccess = () => {
          const rows = (req.result ?? []) as { doc: SyncDocument }[]
          resolve(rows.map((r) => r.doc).filter(Boolean))
        }
        req.onerror = () => reject(req.error)
      })
    },

    async getMeta(key) {
      return new Promise((resolve, reject) => {
        const tx = db.transaction(META_STORE, 'readonly')
        const req = tx.objectStore(META_STORE).get(key)
        req.onsuccess = () => resolve((req.result as never) ?? null)
        req.onerror = () => reject(req.error)
      })
    },

    async setMeta(key, value) {
      const tx = db.transaction(META_STORE, 'readwrite')
      tx.objectStore(META_STORE).put(value, key)
      await txDone(tx)
    },
  }
}
