import type { AppMeta, SyncDocument } from './types'

/** @deprecated LOCALSYNC_DIR nesting has been removed. Layout is now <mapped-root>/<appRootName>/ */
export const LOCALSYNC_DIR = 'localsync'

type DirHandleWithEntries = FileSystemDirectoryHandle & {
  entries: () => AsyncIterableIterator<[string, FileSystemHandle]>
}

export async function* iterateEntries(
  dir: FileSystemDirectoryHandle,
): AsyncGenerator<[string, FileSystemHandle]> {
  const withEntries = dir as DirHandleWithEntries
  if (typeof withEntries.entries === 'function') {
    for await (const entry of withEntries.entries()) {
      yield entry
    }
    return
  }
  // Fallback: values() if present
  const withValues = dir as FileSystemDirectoryHandle & {
    values?: () => AsyncIterableIterator<FileSystemHandle>
  }
  if (typeof withValues.values === 'function') {
    for await (const handle of withValues.values()) {
      yield [handle.name, handle]
    }
  }
}

export function isFolderSyncSupported(): boolean {
  return (
    typeof window !== 'undefined' &&
    typeof (window as unknown as { showDirectoryPicker?: unknown })
      .showDirectoryPicker === 'function' &&
    typeof indexedDB !== 'undefined'
  )
}

export function isNotFoundError(error: unknown): boolean {
  if (!error) return false
  if (error instanceof DOMException && error.name === 'NotFoundError') {
    return true
  }
  if (
    typeof error === 'object' &&
    'name' in error &&
    (error as { name: string }).name === 'NotFoundError'
  ) {
    return true
  }
  if (error instanceof Error) {
    const msg = error.message.toLowerCase()
    return (
      msg.includes('not found') ||
      msg.includes('could not be found') ||
      msg.includes('no such file or directory')
    )
  }
  return false
}

export async function ensurePermission(
  handle: FileSystemDirectoryHandle,
  mode: 'read' | 'readwrite' = 'readwrite',
): Promise<boolean> {
  const withPerm = handle as FileSystemDirectoryHandle & {
    queryPermission?: (o: { mode: string }) => Promise<PermissionState>
    requestPermission?: (o: { mode: string }) => Promise<PermissionState>
  }
  if (typeof withPerm.queryPermission === 'function') {
    let perm = await withPerm.queryPermission({ mode })
    if (perm === 'granted') return true
    if (typeof withPerm.requestPermission === 'function') {
      perm = await withPerm.requestPermission({ mode })
      return perm === 'granted'
    }
    return false
  }
  return true
}

export async function pickDirectory(
  id = 'localsync',
): Promise<FileSystemDirectoryHandle> {
  const picker = (
    window as unknown as {
      showDirectoryPicker: (opts?: {
        id?: string
        mode?: string
      }) => Promise<FileSystemDirectoryHandle>
    }
  ).showDirectoryPicker
  return picker({ id, mode: 'readwrite' })
}

const inflightDirOps = new WeakMap<
  FileSystemDirectoryHandle,
  Map<string, Promise<FileSystemDirectoryHandle>>
>()

/**
 * Idempotent directory resolve:
 * - Case-insensitive match on existing entries in parent.
 * - Reuses existing handle if found (never creates multiple folders with same logical name).
 * - Deduplicates concurrent in-flight requests to prevent duplicate creation races.
 */
export async function getDir(
  parent: FileSystemDirectoryHandle,
  name: string,
  create = false,
): Promise<FileSystemDirectoryHandle> {
  if (!parent) {
    throw new Error('Parent directory handle is required')
  }
  const trimmed = name.trim()
  if (!trimmed || /[/\\]/.test(trimmed) || trimmed === '.' || trimmed === '..') {
    throw new Error(`Invalid directory name: "${name}"`)
  }

  const key = trimmed.toLowerCase()

  let locks = inflightDirOps.get(parent)
  if (!locks) {
    locks = new Map()
    inflightDirOps.set(parent, locks)
  }

  const currentInflight = locks.get(key)
  if (currentInflight) {
    try {
      return await currentInflight
    } catch (e) {
      if (!create) throw e
    }
  }

  const task = (async () => {
    let exactMatch: FileSystemDirectoryHandle | null = null
    let caseMatch: FileSystemDirectoryHandle | null = null

    for await (const [entryName, handle] of iterateEntries(parent)) {
      if (handle.kind === 'directory') {
        if (entryName === trimmed) {
          exactMatch = handle as FileSystemDirectoryHandle
          break
        }
        if (entryName.toLowerCase() === key && !caseMatch) {
          caseMatch = handle as FileSystemDirectoryHandle
        }
      }
    }

    const existing = exactMatch ?? caseMatch
    if (existing) {
      return existing
    }

    if (!create) {
      return parent.getDirectoryHandle(trimmed, { create: false })
    }

    return parent.getDirectoryHandle(trimmed, { create: true })
  })()

  locks.set(key, task)
  try {
    return await task
  } finally {
    locks.delete(key)
  }
}

/**
 * Opens or creates ONLY the single appRootName child under the mapped root.
 * Layout: <mapped-root>/<appRootName>/...
 */
export async function getAppDir(
  root: FileSystemDirectoryHandle,
  appRootName: string,
  create = false,
): Promise<FileSystemDirectoryHandle> {
  const trimmed = appRootName?.trim()
  if (!trimmed || /[/\\]/.test(trimmed)) {
    throw new Error(`getAppDir: invalid appRootName "${appRootName}"`)
  }
  return getDir(root, trimmed, create)
}

export async function readJsonFile<T>(
  dir: FileSystemDirectoryHandle,
  name: string,
): Promise<T | null> {
  try {
    const fh = await dir.getFileHandle(name)
    const file = await fh.getFile()
    const text = await file.text()
    if (!text.trim()) return null
    return JSON.parse(text) as T
  } catch {
    return null
  }
}

export async function writeJsonFile(
  dir: FileSystemDirectoryHandle,
  name: string,
  data: unknown,
): Promise<void> {
  const fh = await dir.getFileHandle(name, { create: true })
  let writable: FileSystemWritableFileStream | null = null
  try {
    writable = await fh.createWritable()
    await writable.write(JSON.stringify(data, null, 2))
    await writable.close()
  } catch (err) {
    if (writable) {
      try {
        await writable.abort()
      } catch {
        /* ignore */
      }
    }
    try {
      await dir.removeEntry(name)
    } catch {
      /* ignore */
    }
    throw err
  }
}

function safeFileName(id: string): string {
  return id.replace(/[/\\?%*:|"<>]/g, '_')
}

export async function readCollectionDocs(
  appDir: FileSystemDirectoryHandle,
  collection: string,
): Promise<SyncDocument[]> {
  try {
    const collections = await getDir(appDir, 'collections', false)
    const colDir = await getDir(collections, collection, false)
    const docs: SyncDocument[] = []
    for await (const [name, handle] of iterateEntries(colDir)) {
      if (handle.kind !== 'file' || !name.endsWith('.json')) continue
      try {
        const file = await (handle as FileSystemFileHandle).getFile()
        const text = await file.text()
        if (!text.trim()) continue
        const doc = JSON.parse(text) as SyncDocument
        if (doc && typeof doc.id === 'string') docs.push(doc)
      } catch {
        /* skip corrupt file */
      }
    }
    return docs
  } catch {
    return []
  }
}

export async function listCollectionNames(
  appDir: FileSystemDirectoryHandle,
): Promise<string[]> {
  try {
    const collections = await getDir(appDir, 'collections', false)
    const names: string[] = []
    for await (const [name, handle] of iterateEntries(collections)) {
      if (handle.kind === 'directory') names.push(name)
    }
    return names
  } catch {
    return []
  }
}

export async function writeDocToFolder(
  appDir: FileSystemDirectoryHandle,
  doc: SyncDocument,
): Promise<void> {
  const collections = await getDir(appDir, 'collections', true)
  const colDir = await getDir(collections, doc.collection, true)
  await writeJsonFile(colDir, `${safeFileName(doc.id)}.json`, doc)
}

export async function writeMeta(
  appDir: FileSystemDirectoryHandle,
  appRootName: string,
): Promise<void> {
  const meta: AppMeta = {
    version: 1,
    appRootName,
    appId: appRootName,
    updatedAt: new Date().toISOString(),
  }
  await writeJsonFile(appDir, 'meta.json', meta)
}

export async function writeBlob(
  appDir: FileSystemDirectoryHandle,
  collection: string,
  docId: string,
  blobKey: string,
  data: BufferSource | Blob | string,
): Promise<void> {
  const blobs = await getDir(appDir, 'blobs', true)
  const colDir = await getDir(blobs, collection, true)
  const docDir = await getDir(colDir, safeFileName(docId), true)
  const fh = await docDir.getFileHandle(safeFileName(blobKey), { create: true })
  let writable: FileSystemWritableFileStream | null = null
  try {
    writable = await fh.createWritable()
    await writable.write(data)
    await writable.close()
  } catch (err) {
    if (writable) {
      try {
        await writable.abort()
      } catch {
        /* ignore */
      }
    }
    try {
      await docDir.removeEntry(safeFileName(blobKey))
    } catch {
      /* ignore */
    }
    throw err
  }
}

export async function readBlob(
  appDir: FileSystemDirectoryHandle,
  collection: string,
  docId: string,
  blobKey: string,
): Promise<Blob | null> {
  try {
    const blobs = await getDir(appDir, 'blobs', false)
    const colDir = await getDir(blobs, collection, false)
    const docDir = await getDir(colDir, safeFileName(docId), false)
    const fh = await docDir.getFileHandle(safeFileName(blobKey))
    return fh.getFile()
  } catch {
    return null
  }
}
