import type { LocalSync } from './createLocalSync'
import type { LocalSyncState, SyncDocument } from './types'

export type ExplorerNodeKind = 'folder' | 'file'

export interface ExplorerFolderNode {
  kind: 'folder'
  id: string
  name: string
  parentId: string | null
  path: string
}

export interface ExplorerFileNode {
  kind: 'file'
  id: string
  collection: string
  name: string
  parentId: string | null
  path: string
  doc: SyncDocument
}

export type ExplorerNode = ExplorerFolderNode | ExplorerFileNode

export interface FolderPayload {
  name: string
  parentId: string | null
}

export interface PlacementPayload {
  collection: string
  docId: string
  parentId: string | null
  name?: string
}

export interface CreateExplorerOptions {
  collections: string[]
  foldersCollection?: string
  placementsCollection?: string
  getDisplayName?: (doc: SyncDocument) => string
}

export interface Explorer {
  listChildren: (parentId?: string | null) => Promise<ExplorerNode[]>
  getTree: () => Promise<ExplorerNode[]>
  createFolder: (name: string, parentId?: string | null) => Promise<ExplorerFolderNode>
  rename: {
    (node: ExplorerFolderNode, newName: string): Promise<ExplorerFolderNode>
    (node: ExplorerFileNode, newName: string): Promise<ExplorerFileNode>
    (node: ExplorerNode, newName: string): Promise<ExplorerNode>
  }
  move: {
    (node: ExplorerFolderNode, newParentId: string | null): Promise<ExplorerFolderNode>
    (node: ExplorerFileNode, newParentId: string | null): Promise<ExplorerFileNode>
    (node: ExplorerNode, newParentId: string | null): Promise<ExplorerNode>
  }
  delete: (node: ExplorerNode, opts?: { recursive?: boolean }) => Promise<void>
  permanentDelete: (node: ExplorerNode, opts?: { recursive?: boolean }) => Promise<void>
  ensurePlacement: (
    collection: string,
    docId: string,
    parentId?: string | null,
    name?: string,
  ) => Promise<SyncDocument<PlacementPayload>>
  subscribe: (listener: (state: LocalSyncState) => void) => () => void
}

export function validateName(name: string): string {
  if (typeof name !== 'string') {
    throw new Error('Name must be a non-empty string')
  }
  const trimmed = name.trim()
  if (!trimmed) {
    throw new Error('Name cannot be empty')
  }
  if (/[/\\]/.test(trimmed)) {
    throw new Error('Name cannot contain slashes ("/" or "\\")')
  }
  if (trimmed === '.' || trimmed === '..') {
    throw new Error('Name cannot be "." or ".."')
  }
  return trimmed
}

export function sortExplorerNodes(nodes: ExplorerNode[]): ExplorerNode[] {
  return [...nodes].sort((a, b) => {
    if (a.kind !== b.kind) {
      return a.kind === 'folder' ? -1 : 1
    }
    const cmp = a.name.localeCompare(b.name, undefined, { sensitivity: 'base' })
    if (cmp !== 0) return cmp
    return a.id.localeCompare(b.id)
  })
}

function generateFolderId(): string {
  if (
    typeof crypto !== 'undefined' &&
    typeof crypto.randomUUID === 'function'
  ) {
    return crypto.randomUUID()
  }
  return 'f_' + Math.random().toString(36).substring(2, 11) + Date.now().toString(36)
}

function placementKey(collection: string, docId: string): string {
  return `${collection}:${docId}`
}

function computeFolderPath(
  folderId: string,
  foldersById: Map<string, FolderPayload>,
): string {
  const segments: string[] = []
  const visited = new Set<string>()
  let curr: string | null = folderId
  while (curr !== null) {
    if (visited.has(curr)) break
    visited.add(curr)
    const folder = foldersById.get(curr)
    if (!folder) break
    segments.unshift(folder.name)
    curr = folder.parentId
  }
  return '/' + segments.join('/')
}

function computeFilePath(
  parentId: string | null,
  fileName: string,
  foldersById: Map<string, FolderPayload>,
): string {
  if (!parentId) {
    return `/${fileName}`
  }
  const folderPath = computeFolderPath(parentId, foldersById)
  if (!folderPath || folderPath === '/') {
    return `/${fileName}`
  }
  return `${folderPath}/${fileName}`
}

function resolveFileDisplayName(
  doc: SyncDocument,
  placementName?: string,
  getDisplayName?: (doc: SyncDocument) => string,
): string {
  if (placementName && placementName.trim()) {
    return placementName.trim()
  }
  if (getDisplayName) {
    const custom = getDisplayName(doc)
    if (custom && custom.trim()) {
      return custom.trim()
    }
  }
  const payload = doc.payload as Record<string, unknown> | null | undefined
  if (payload && typeof payload === 'object') {
    if (typeof payload.name === 'string' && payload.name.trim()) {
      return payload.name.trim()
    }
    if (typeof payload.title === 'string' && payload.title.trim()) {
      return payload.title.trim()
    }
  }
  return doc.id
}

export function createExplorer(
  sync: LocalSync,
  options: CreateExplorerOptions,
): Explorer {
  if (!options || !Array.isArray(options.collections)) {
    throw new Error('createExplorer: options.collections must be an array')
  }

  const collections = [...options.collections]
  const foldersCollection = options.foldersCollection ?? '_folders'
  const placementsCollection = options.placementsCollection ?? '_placements'
  const getDisplayName = options.getDisplayName

  async function getFoldersMap(): Promise<{
    allFolders: SyncDocument<FolderPayload>[]
    foldersById: Map<string, FolderPayload>
  }> {
    const allFolders = await sync.list<FolderPayload>(foldersCollection)
    const foldersById = new Map<string, FolderPayload>()
    for (const f of allFolders) {
      foldersById.set(f.id, f.payload)
    }
    return { allFolders, foldersById }
  }

  async function getPlacementsMap(): Promise<Map<string, PlacementPayload>> {
    const placementDocs = await sync.list<PlacementPayload>(placementsCollection)
    const map = new Map<string, PlacementPayload>()
    for (const p of placementDocs) {
      map.set(placementKey(p.payload.collection, p.payload.docId), p.payload)
      map.set(p.id, p.payload)
    }
    return map
  }

  async function listChildren(parentId?: string | null): Promise<ExplorerNode[]> {
    const targetParentId = parentId ?? null

    if (targetParentId !== null) {
      const parent = await sync.get<FolderPayload>(foldersCollection, targetParentId)
      if (!parent) {
        throw new Error(`Folder "${targetParentId}" not found`)
      }
    }

    const { allFolders, foldersById } = await getFoldersMap()
    const folderNodes: ExplorerFolderNode[] = allFolders
      .filter((f) => (f.payload.parentId ?? null) === targetParentId)
      .map((f) => ({
        kind: 'folder' as const,
        id: f.id,
        name: f.payload.name,
        parentId: f.payload.parentId ?? null,
        path: computeFolderPath(f.id, foldersById),
      }))

    const placementMap = await getPlacementsMap()
    const fileNodes: ExplorerFileNode[] = []

    for (const col of collections) {
      const docs = await sync.list(col)
      for (const doc of docs) {
        const placement = placementMap.get(placementKey(doc.collection, doc.id))
        const docParentId = placement?.parentId ?? null
        if (docParentId === targetParentId) {
          const displayName = resolveFileDisplayName(
            doc,
            placement?.name,
            getDisplayName,
          )
          fileNodes.push({
            kind: 'file' as const,
            id: doc.id,
            collection: doc.collection,
            name: displayName,
            parentId: docParentId,
            path: computeFilePath(docParentId, displayName, foldersById),
            doc,
          })
        }
      }
    }

    return sortExplorerNodes([...folderNodes, ...fileNodes])
  }

  async function getTree(): Promise<ExplorerNode[]> {
    const { allFolders, foldersById } = await getFoldersMap()
    const placementMap = await getPlacementsMap()

    // Build map of folders and files grouped by parentId
    const foldersByParent = new Map<string | null, ExplorerFolderNode[]>()
    for (const f of allFolders) {
      const pId = f.payload.parentId ?? null
      const node: ExplorerFolderNode = {
        kind: 'folder',
        id: f.id,
        name: f.payload.name,
        parentId: pId,
        path: computeFolderPath(f.id, foldersById),
      }
      if (!foldersByParent.has(pId)) {
        foldersByParent.set(pId, [])
      }
      foldersByParent.get(pId)!.push(node)
    }

    const filesByParent = new Map<string | null, ExplorerFileNode[]>()
    for (const col of collections) {
      const docs = await sync.list(col)
      for (const doc of docs) {
        const placement = placementMap.get(placementKey(doc.collection, doc.id))
        const docParentId = placement?.parentId ?? null
        const displayName = resolveFileDisplayName(
          doc,
          placement?.name,
          getDisplayName,
        )
        const node: ExplorerFileNode = {
          kind: 'file',
          id: doc.id,
          collection: doc.collection,
          name: displayName,
          parentId: docParentId,
          path: computeFilePath(docParentId, displayName, foldersById),
          doc,
        }
        if (!filesByParent.has(docParentId)) {
          filesByParent.set(docParentId, [])
        }
        filesByParent.get(docParentId)!.push(node)
      }
    }

    const result: ExplorerNode[] = []
    const visitedFolders = new Set<string>()

    function traverse(currentParentId: string | null): void {
      const childFolders = foldersByParent.get(currentParentId) ?? []
      const childFiles = filesByParent.get(currentParentId) ?? []
      const sortedChildFolders = sortExplorerNodes(childFolders) as ExplorerFolderNode[]
      const sortedChildFiles = sortExplorerNodes(childFiles) as ExplorerFileNode[]

      for (const folder of sortedChildFolders) {
        result.push(folder)
        if (!visitedFolders.has(folder.id)) {
          visitedFolders.add(folder.id)
          traverse(folder.id)
        }
      }

      for (const file of sortedChildFiles) {
        result.push(file)
      }
    }

    traverse(null)

    // Handle any orphaned folders or files whose parents were not reached
    for (const [pId, fList] of foldersByParent.entries()) {
      if (pId !== null && !visitedFolders.has(pId)) {
        for (const f of fList) {
          if (!visitedFolders.has(f.id)) {
            visitedFolders.add(f.id)
            result.push(f)
            traverse(f.id)
          }
        }
      }
    }

    for (const [pId, fileList] of filesByParent.entries()) {
      if (pId !== null && !visitedFolders.has(pId)) {
        for (const file of fileList) {
          if (!result.includes(file)) {
            result.push(file)
          }
        }
      }
    }

    return result
  }

  async function createFolder(
    name: string,
    parentId?: string | null,
  ): Promise<ExplorerFolderNode> {
    const validName = validateName(name)
    const targetParentId = parentId ?? null

    if (targetParentId !== null) {
      const parent = await sync.get<FolderPayload>(foldersCollection, targetParentId)
      if (!parent) {
        throw new Error(`Parent folder "${targetParentId}" not found`)
      }
    }

    const id = generateFolderId()
    const payload: FolderPayload = {
      name: validName,
      parentId: targetParentId,
    }
    await sync.put<FolderPayload>(foldersCollection, id, payload)

    const { foldersById } = await getFoldersMap()
    foldersById.set(id, payload)

    return {
      kind: 'folder',
      id,
      name: validName,
      parentId: targetParentId,
      path: computeFolderPath(id, foldersById),
    }
  }

  async function rename(node: ExplorerNode, newName: string): Promise<ExplorerNode> {
    const validName = validateName(newName)

    if (node.kind === 'folder') {
      const existing = await sync.get<FolderPayload>(foldersCollection, node.id)
      if (!existing) {
        throw new Error(`Folder "${node.id}" not found`)
      }
      const updatedPayload: FolderPayload = {
        ...existing.payload,
        name: validName,
      }
      await sync.put<FolderPayload>(foldersCollection, node.id, updatedPayload)
      const { foldersById } = await getFoldersMap()
      foldersById.set(node.id, updatedPayload)
      return {
        kind: 'folder',
        id: node.id,
        name: validName,
        parentId: updatedPayload.parentId,
        path: computeFolderPath(node.id, foldersById),
      }
    } else {
      const key = placementKey(node.collection, node.id)
      const existingPlacement = await sync.get<PlacementPayload>(placementsCollection, key)
      const updatedPayload: PlacementPayload = {
        collection: node.collection,
        docId: node.id,
        parentId: existingPlacement?.payload.parentId ?? node.parentId ?? null,
        name: validName,
      }
      await sync.put<PlacementPayload>(placementsCollection, key, updatedPayload)
      const { foldersById } = await getFoldersMap()
      return {
        ...node,
        name: validName,
        parentId: updatedPayload.parentId,
        path: computeFilePath(updatedPayload.parentId, validName, foldersById),
      }
    }
  }

  async function move(
    node: ExplorerNode,
    newParentId: string | null,
  ): Promise<ExplorerNode> {
    const targetParentId = newParentId ?? null

    if (targetParentId !== null) {
      const parent = await sync.get<FolderPayload>(foldersCollection, targetParentId)
      if (!parent) {
        throw new Error(`Target folder "${targetParentId}" not found`)
      }
    }

    if (node.kind === 'folder') {
      if (node.id === targetParentId) {
        throw new Error('Cannot move folder into itself')
      }

      if (targetParentId !== null) {
        const { foldersById } = await getFoldersMap()
        let curr: string | null = targetParentId
        const visited = new Set<string>()
        while (curr !== null) {
          if (curr === node.id) {
            throw new Error('Cannot move folder into its own descendant')
          }
          if (visited.has(curr)) break
          visited.add(curr)
          curr = foldersById.get(curr)?.parentId ?? null
        }
      }

      const existing = await sync.get<FolderPayload>(foldersCollection, node.id)
      if (!existing) {
        throw new Error(`Folder "${node.id}" not found`)
      }
      const updatedPayload: FolderPayload = {
        ...existing.payload,
        parentId: targetParentId,
      }
      await sync.put<FolderPayload>(foldersCollection, node.id, updatedPayload)
      const { foldersById } = await getFoldersMap()
      foldersById.set(node.id, updatedPayload)
      return {
        kind: 'folder',
        id: node.id,
        name: updatedPayload.name,
        parentId: targetParentId,
        path: computeFolderPath(node.id, foldersById),
      }
    } else {
      const key = placementKey(node.collection, node.id)
      const existing = await sync.get<PlacementPayload>(placementsCollection, key)
      const updatedPayload: PlacementPayload = {
        collection: node.collection,
        docId: node.id,
        parentId: targetParentId,
        ...(existing?.payload.name ? { name: existing.payload.name } : {}),
      }
      await sync.put<PlacementPayload>(placementsCollection, key, updatedPayload)
      const { foldersById } = await getFoldersMap()
      return {
        ...node,
        parentId: targetParentId,
        path: computeFilePath(targetParentId, node.name, foldersById),
      }
    }
  }

  async function collectDescendants(folderId: string): Promise<{
    folderIds: string[]
    files: { collection: string; id: string }[]
  }> {
    const { allFolders } = await getFoldersMap()
    const folderIdsToDelete = new Set<string>([folderId])

    let changed = true
    while (changed) {
      changed = false
      for (const f of allFolders) {
        if (
          f.payload.parentId &&
          folderIdsToDelete.has(f.payload.parentId) &&
          !folderIdsToDelete.has(f.id)
        ) {
          folderIdsToDelete.add(f.id)
          changed = true
        }
      }
    }

    const placementMap = await getPlacementsMap()
    const files: { collection: string; id: string }[] = []

    for (const col of collections) {
      const docs = await sync.list(col)
      for (const doc of docs) {
        const placement = placementMap.get(placementKey(doc.collection, doc.id))
        const pId = placement?.parentId ?? null
        if (pId && folderIdsToDelete.has(pId)) {
          files.push({ collection: doc.collection, id: doc.id })
        }
      }
    }

    return {
      folderIds: Array.from(folderIdsToDelete),
      files,
    }
  }

  async function deleteNode(
    node: ExplorerNode,
    opts?: { recursive?: boolean },
  ): Promise<void> {
    if (node.kind === 'file') {
      await sync.delete(node.collection, node.id)
      await sync.delete(placementsCollection, placementKey(node.collection, node.id))
      return
    }

    const { folderIds, files } = await collectDescendants(node.id)
    const hasChildren = folderIds.length > 1 || files.length > 0
    if (!opts?.recursive && hasChildren) {
      throw new Error(
        `Cannot delete folder "${node.name}" because it is not empty. Pass recursive: true to delete.`,
      )
    }

    for (const file of files) {
      await sync.delete(file.collection, file.id)
      await sync.delete(placementsCollection, placementKey(file.collection, file.id))
    }

    for (const fId of folderIds) {
      await sync.delete(foldersCollection, fId)
    }
  }

  async function permanentDeleteNode(
    node: ExplorerNode,
    opts?: { recursive?: boolean },
  ): Promise<void> {
    if (node.kind === 'file') {
      await sync.hardDelete(node.collection, node.id)
      await sync.hardDelete(placementsCollection, placementKey(node.collection, node.id))
      return
    }

    const { folderIds, files } = await collectDescendants(node.id)
    const hasChildren = folderIds.length > 1 || files.length > 0
    if (!opts?.recursive && hasChildren) {
      throw new Error(
        `Cannot delete folder "${node.name}" because it is not empty. Pass recursive: true to delete.`,
      )
    }

    for (const file of files) {
      await sync.hardDelete(file.collection, file.id)
      await sync.hardDelete(placementsCollection, placementKey(file.collection, file.id))
    }

    for (const fId of folderIds) {
      await sync.hardDelete(foldersCollection, fId)
    }
  }

  async function ensurePlacement(
    collection: string,
    docId: string,
    parentId?: string | null,
    name?: string,
  ): Promise<SyncDocument<PlacementPayload>> {
    if (parentId !== undefined && parentId !== null) {
      const folder = await sync.get<FolderPayload>(foldersCollection, parentId)
      if (!folder) {
        throw new Error(`Parent folder "${parentId}" not found`)
      }
    }

    const key = placementKey(collection, docId)
    const existing = await sync.get<PlacementPayload>(placementsCollection, key)
    const resolvedParentId =
      parentId !== undefined
        ? parentId
        : existing?.payload.parentId !== undefined
          ? existing.payload.parentId
          : null

    let resolvedName: string | undefined = undefined
    if (name !== undefined) {
      resolvedName = validateName(name)
    } else if (existing?.payload.name !== undefined) {
      resolvedName = existing.payload.name
    }

    const payload: PlacementPayload = {
      collection,
      docId,
      parentId: resolvedParentId,
      ...(resolvedName ? { name: resolvedName } : {}),
    }

    return sync.put<PlacementPayload>(placementsCollection, key, payload)
  }

  return {
    listChildren,
    getTree,
    createFolder,
    rename: rename as Explorer['rename'],
    move: move as Explorer['move'],
    delete: deleteNode,
    permanentDelete: permanentDeleteNode,
    ensurePlacement,
    subscribe: (listener: (state: LocalSyncState) => void) => sync.subscribe(listener),
  }
}
